    targets: [], cancers: ["hcc","metastatic-cancer","all-leukemia"], companies: ["ascentawits-pharmaceuticals","obi-pharma","zhejiang-hisun"], trials: ["nct06239155","nct07310173","nct04315324","nct03592264"],
